/** Throws a RangeError when `timeZone` is not a zone Intl recognises. */
export function assertTimeZone(timeZone: string): void {
  zoneFormatter(timeZone);
}

interface WallClock {
  year: number;
  month: number;
  day: number;
  hour: number;
  minute: number;
  second: number;
}

function wallClock(instantMs: number, timeZone: string): WallClock {
  const out: Record<string, number> = {};
  for (const part of zoneFormatter(timeZone).formatToParts(new Date(instantMs))) {
    if (part.type !== "literal") out[part.type] = Number(part.value);
  }
  return {
    year: out.year ?? 0,
    month: out.month ?? 1,
    day: out.day ?? 1,
    hour: (out.hour ?? 0) % 24,
    minute: out.minute ?? 0,
    second: out.second ?? 0,
  };
}

/** The wall clock read as if it were UTC, in ms. */
function wallAsUtcMs(w: WallClock): number {
  return Date.UTC(w.year, w.month - 1, w.day, w.hour, w.minute, w.second);
}

function offsetMs(instantMs: number, timeZone: string): number {
  const truncated = Math.floor(instantMs / 1000) * 1000;
  return wallAsUtcMs(wallClock(truncated, timeZone)) - truncated;
}

/**
 * Every instant at which the zone's wall clock reads `year-month-day hour:00`
 * (two across a DST fall-back, none inside a spring-forward gap), ascending.
 */
function wallInstants(
  year: number,
  month: number,
  day: number,
  hour: number,
  timeZone: string,
): number[] {
  const target = Date.UTC(year, month - 1, day, hour, 0, 0);
  const offsets = new Set([
    offsetMs(target - DAY_MS, timeZone),
    offsetMs(target, timeZone),
    offsetMs(target + DAY_MS, timeZone),
  ]);
  const found = new Set<number>();
  for (const offset of offsets) {
    const candidate = target - offset;
    if (wallAsUtcMs(wallClock(candidate, timeZone)) === target) found.add(candidate);
  }
  return [...found].sort((a, b) => a - b);
}

/**
 * First instant whose wall clock is at or after `hour:00` on the given date;
 * inside a gap that is the moment the gap ends.
 */
function firstInstantAtOrAfter(
  year: number,
  month: number,
  day: number,
  hour: number,
  timeZone: string,
): number {
  const exact = wallInstants(year, month, day, hour, timeZone);
  if (exact.length > 0) return exact[0] as number;
  const target = Date.UTC(year, month - 1, day, hour, 0, 0);
  // Gap: the transition happens where the earlier offset makes the clock hit `target`.
  return target - offsetMs(target - DAY_MS, timeZone);
}

function shiftDate(
  year: number,
  month: number,
  day: number,
  days: number,
): { year: number; month: number; day: number } {
  const d = new Date(Date.UTC(year, month - 1, day + days));
  return { year: d.getUTCFullYear(), month: d.getUTCMonth() + 1, day: d.getUTCDate() };
}

function pad(n: number, width = 2): string {
  return String(n).padStart(width, "0");
}

/** The `YYYY-MM-DD` calendar date of an instant in the given zone. */
export function localDate(value: IsoTimestamp, timeZone: string): string {
  const w = wallClock(parseIso(value).getTime(), timeZone);
  return `${pad(w.year, 4)}-${pad(w.month)}-${pad(w.day)}`;
}

/** The UTC instant at which the zone's calendar day containing `reference` began. */
export function startOfLocalDay(reference: Date, timeZone: string): IsoTimestamp {
  const w = wallClock(reference.getTime(), timeZone);
  return toIsoTimestamp(
    new Date(firstInstantAtOrAfter(w.year, w.month, w.day, 0, timeZone)),
  );
}

/**
 * Due dates are whole days: an issue is overdue once the workspace-clock day
 * containing `dueAt` has ended.
 */
export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
  timeZone = "UTC",
): boolean {
  if (dueAt === null) return false;
  return (
    localDate(dueAt, timeZone) <
    localDate(toIsoTimestamp(reference), timeZone)
  );
}

