new_win='''/**
 * The window a digest covers: it ends at the most recent local `digestHour:00`
 * at or before `reference` and starts at the same local hour on the previous
 * calendar day (23 or 25 hours across a DST change).
 */
export function digestWindow(
  digestHour: number,
  reference: Date,
  timeZone = "UTC",
): { start: IsoTimestamp; end: IsoTimestamp } {
  if (!Number.isInteger(digestHour) || digestHour < 0 || digestHour > 23) {
    throw new RangeError(`digestHour must be 0-23, got ${digestHour}`);
  }

  const refMs = reference.getTime();
  const today = wallClock(refMs, timeZone);
  let end: number | null = null;
  let endDate = today;
  for (const back of [0, 1, 2]) {
    const d = shiftDate(today.year, today.month, today.day, -back);
    const at = wallInstants(d.year, d.month, d.day, digestHour, timeZone).filter(
      (t) => t <= refMs,
    );
    if (at.length > 0) {
      end = at[at.length - 1] as number;
      endDate = { ...today, ...d };
      break;
    }
  }
  if (end === null) {
    // Every recent occurrence fell in a gap; fall back to the gap's end.
    const d = shiftDate(today.year, today.month, today.day, -1);
    end = firstInstantAtOrAfter(d.year, d.month, d.day, digestHour, timeZone);
    endDate = { ...today, ...d };
  }

  const prev = shiftDate(endDate.year, endDate.month, endDate.day, -1);
  const start = firstInstantAtOrAfter(prev.year, prev.month, prev.day, digestHour, timeZone);

  return { start: toIsoTimestamp(new Date(start)), end: toIsoTimestamp(new Date(end)) };
}
